contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public {
        require(to != address(0), "recipient is zero");

        uint256 senderBalanceBefore = c.balanceOf(address(this));
        uint256 recipientBalanceBefore = c.balanceOf(to);
        uint256 totalSupplyBefore = c.totalSupply();
        bool senderFrozenBefore = c.frozenAccount(address(this));
        bool recipientFrozenBefore = c.frozenAccount(to);

        require(senderBalanceBefore >= amount, "insufficient balance");
        require(recipientBalanceBefore + amount >= recipientBalanceBefore, "overflow");
        require(!senderFrozenBefore, "sender frozen");
        require(!recipientFrozenBefore, "recipient frozen");

        bool success = c.transfer(to, amount);

        uint256 senderBalanceAfter = c.balanceOf(address(this));
        uint256 recipientBalanceAfter = c.balanceOf(to);
        uint256 totalSupplyAfter = c.totalSupply();

        assert(success && senderBalanceAfter == senderBalanceBefore - amount && recipientBalanceAfter == recipientBalanceBefore + amount && totalSupplyAfter == totalSupplyBefore);
    }
}

